 line(x1,y1,x2,y2,color=C.line,width=1,arrow=false){this.record('connector',Math.min(x1,x2),Math.min(y1,y2),Math.abs(x2-x1),Math.abs(y2-y1));let i=this.id++;this.s.push(`<p:cxnSp><p:nvCxnSpPr><p:cNvPr id="${i}" name="Connector ${i}"/><p:cNvCxnSpPr/><p:nvPr/></p:nvCxnSpPr><p:spPr><a:xfrm${x2<x1?' flipH="1"':''}${y2<y1?' flipV="1"':''}><a:off x="${em(Math.min(x1,x2))}" y="${em(Math.min(y1,y2))}"/><a:ext cx="${em(Math.abs(x2-x1))}" cy="${em(Math.abs(y2-y1))}"/></a:xfrm><a:prstGeom prst="line"><a:avLst/></a:prstGeom><a:ln w="${Math.round(width*12700)}"><a:solidFill><a:srgbClr val="${color}"/></a:solidFill>${arrow?'<a:tailEnd type="triangle" w="sm" len="sm"/>':''}</a:ln></p:spPr><p:style><a:lnRef idx="0"><a:schemeClr val="accent1"/></a:lnRef><a:fillRef idx="0"><a:schemeClr val="accent1"/></a:fillRef><a:effectRef idx="0"><a:schemeClr val="accent1"/></a:effectRef><a:fontRef idx="minor"><a:schemeClr val="lt1"/></a:fontRef></p:style></p:cxnSp>`);}
