{
const s=new Slide('The evaluation we actually completed','OUR RESEARCH  |  PRELIMINARY STUDY','Exploratory development comparison · real model outputs · AI-simulated feedback');
s.text(.85,2.12,11.6,.65,'8 groups × 3 conditions × 6 methods × 27 = 3,888 answers',{size:27,bold:true,color:C.navy});
lead(s,'Inputs','256 distinct cases: 128 Email + 128 File/Document. The same bags recur across conditions.',3.25);lead(s,'Methods','No-memory control; static SAFE-Mem; R; C; M; S. Five shared audit tickets for R/C/M/S.',4.35);lead(s,'Endpoints','Original ASR, explicit retention, restraint and combined benign utility. External-source QA is unavailable.',5.45);caption(s,'D00 ran first; every remaining existing development group D01–D07 was then included without changing the methods.');
s.note('The run covers the eight pre-existing development groups D00–D07, not all twenty prepared groups and not the full 6,240-case pool. There are 160 original attack inputs and 96 benign inputs before audits reserve five cases per group. Per method: 648 answers total, 216 per regime. Across six methods: 3,888 answer events. Repeated overlays are paired sensitivity conditions, not independent datasets. The original source-grounded benign question set was unvalidated and not scored; its unavailable metric is not zero. D00 had no originally admitted external candidate. The extension used every remaining pre-existing development bag without outcome-based selection or new tuning. Primary comparisons are S against C and M at equal feedback/resources, with R and static as additional references and no-memory as a diagnostic extreme. Statistical reporting uses paired bag bootstrap, 10,000 resamples, exploratory pointwise intervals; neither equivalence nor noninferiority is established.',[SRC.pilot,SRC.results]);}
function resultSlide(title,indices,metrics,detail){const s=new Slide(title,'OUR RESEARCH  |  PRELIMINARY RESULTS','Results (%) · 256 distinct inputs · 8 development groups · proposed S has NOT been evaluated on full MPBench');const t=DATA.tables[1];const methWidth=3.3,metricW=(12-methWidth)/6;const headers=['Method'];for(let k=0;k<3;k++)headers.push(...metrics);const rows=t.rows.map(r=>[{text:({'no_memory':'No memory (control)','static':'Static SAFE-Mem','R':'Record-only (R)','C':'Contextual (C)','M':'Multi-scope (M)','S':'Selective propagation (ours)'})[r.key]??r.label},...indices.flatMap((ix,k)=>ix.map(j=>{const c=r.cells[k*4+j];return {text:c.display,bold:c.best}}))]);for(let k=0;k<3;k++){let x=.65+methWidth+k*2*metricW;s.text(x,2.05,2*metricW,.35,['Distributed','Localized','Uninformative'][k],{size:20,bold:true,align:'ctr',font:'Times New Roman'});s.line(x+.13,2.53,x+2*metricW-.13,2.53,C.ink,.75);}s.table(.65,2.65,12,headers,rows,{widths:[methWidth,...Array(6).fill(metricW)],size:17,rowHeight:.49,headerHeight:.55,oursLast:true});s.text(.75,6.48,11.7,.32,detail,{size:17,color:C.teal});caption(s,'Bold: best, including ties and control. Source-grounded benign QA is unavailable (-) for every method.',6.86);return s;}
